import {Pacman,COLS,ROWS,DIRS} from './rules.js';
const $=s=>document.querySelector(s),canvas=$('#board'),c=canvas.getContext('2d'),S=24;
let game=new Pacman(),started=false,last=performance.now(),time=0,best=0,sound=false,audio=null,swipe=null,notesPaused=false,lastOverlay='';
try{best=Number(localStorage.getItem('po-pacman-best'))||0}catch{}
const effects=[];$('#best').textContent=String(best).padStart(6,'0');
function tone(f=350,duration=.08){if(!sound)return;const A=window.AudioContext||window.webkitAudioContext;if(!A)return;audio??=new A();audio.resume().catch(()=>{});const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.55,audio.currentTime+duration);g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
function wall(x,y){const px=x*S,py=y*S;c.fillStyle='#071437';c.fillRect(px,py,S,S);c.strokeStyle='#3265ff';c.lineWidth=2.2;c.lineCap='round';c.shadowColor='#1749ff';c.shadowBlur=4;const open=(nx,ny)=>ny>=0&&ny<ROWS&&nx>=0&&nx<COLS&&game.board[ny][nx]!=='#';c.beginPath();if(open(x,y-1)){c.moveTo(px+2,py+3);c.lineTo(px+22,py+3)}if(open(x,y+1)){c.moveTo(px+2,py+21);c.lineTo(px+22,py+21)}if(open(x-1,y)){c.moveTo(px+3,py+2);c.lineTo(px+3,py+22)}if(open(x+1,y)){c.moveTo(px+21,py+2);c.lineTo(px+21,py+22)}c.stroke();c.shadowBlur=0}
function pac(x,y){let mouth=.18+(.5+.5*Math.sin(time*24))*.42;if(game.state==='dying')mouth=Math.min(Math.PI,Math.PI*(1-game.wait/1.6));c.save();c.translate(x,y);c.rotate(Math.max(0,game.player.dir)*Math.PI/2);c.fillStyle='#ffe235';c.shadowColor='#ffcf3155';c.shadowBlur=8;c.beginPath();c.moveTo(0,0);c.arc(0,0,10,mouth,Math.PI*2-mouth);c.closePath();c.fill();c.restore()}
function ghost(g,x,y){const fright=game.fright>0&&g.mode==='active',blink=game.fright<2&&Math.floor(time*7)%2===0,eyesOnly=g.mode==='return';c.save();c.translate(x,y);if(!eyesOnly){c.fillStyle=fright?(blink?'#f2eef6':'#254fff'):g.color;c.beginPath();c.moveTo(-10,9);c.lineTo(-10,-1);c.arc(0,-1,10,Math.PI,0);c.lineTo(10,9);for(let i=0;i<5;i++)c.lineTo(10-i*5,6+((i+Math.floor(time*8))%2)*4);c.closePath();c.fill()}
 if(fright){c.fillStyle=blink?'#e64d58':'#fff4bd';c.fillRect(-5,-3,3,3);c.fillRect(3,-3,3,3);c.strokeStyle=c.fillStyle;c.lineWidth=1.4;c.beginPath();c.moveTo(-6,5);for(let i=0;i<6;i++)c.lineTo(-6+i*2.4,4+(i%2)*2);c.stroke()}else{const d=DIRS[Math.max(0,g.dir)];for(const ex of [-4.5,4.5]){c.fillStyle='#fff';c.beginPath();c.ellipse(ex,-2,4.4,5.1,0,0,Math.PI*2);c.fill();c.fillStyle='#234ec9';c.beginPath();c.arc(ex+d.x*2,-2+d.y*2,2.2,0,Math.PI*2);c.fill()}}c.restore()}
function cherries(x,y){c.strokeStyle='#72ca5e';c.lineWidth=2;c.beginPath();c.moveTo(x-4,y);c.quadraticCurveTo(x-1,y-14,x+7,y-13);c.quadraticCurveTo(x+2,y-7,x+5,y);c.stroke();c.fillStyle='#f04d6b';for(const dx of [-5,6]){c.beginPath();c.arc(x+dx,y+4,5,0,Math.PI*2);c.fill()}c.fillStyle='#ffafbf';c.fillRect(x-8,y+1,2,2)}
function draw(){c.fillStyle='#020716';c.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){if(game.board[y][x]==='#')wall(x,y);if(game.board[y][x]==='-'){c.strokeStyle='#ffa2d2';c.lineWidth=2;c.beginPath();c.moveTo(x*S,y*S+S/2);c.lineTo((x+1)*S,y*S+S/2);c.stroke()}}
 for(const [pos,type]of game.pellets){const [x,y]=pos.split(',').map(Number);if(type==='o'&&Math.sin(time*7)<-.25)continue;c.fillStyle='#ffdfad';c.beginPath();c.arc(x*S+S/2,y*S+S/2,type==='o'?5:2.1,0,Math.PI*2);c.fill()}
 if(game.fruit)cherries(game.fruit.x*S+S/2,game.fruit.y*S+S/2);
 const p=game.player;if(game.state!=='over')for(const offset of [-COLS,0,COLS])pac((p.x+offset)*S+S/2,p.y*S+S/2);
 for(const g of game.ghosts)for(const offset of [-COLS,0,COLS])ghost(g,(g.x+offset)*S+S/2,g.y*S+S/2);
 c.font='bold 12px monospace';c.textAlign='center';for(const e of effects){c.globalAlpha=Math.min(1,e.life*2);c.fillStyle='#9effe1';c.fillText(e.text,e.x*S+12,e.y*S+12-(1-e.life)*15)}c.globalAlpha=1;
}
function hud(){$('#score').textContent=String(game.score).padStart(6,'0');$('#level').textContent=String(game.level).padStart(2,'0');$('#lives').textContent='● '.repeat(game.lives);if(game.score>best){best=game.score;$('#best').textContent=String(best).padStart(6,'0');try{localStorage.setItem('po-pacman-best',String(best))}catch{}}
 const state=started?game.state:'menu';if(lastOverlay===state)return;lastOverlay=state;$('#overlay').hidden=!started||state==='playing'||state==='dying';$('#again').hidden=state!=='over';$('#overlay').style.pointerEvents=state==='over'?'auto':'none';$('#overlay-title').textContent={ready:'READY!',paused:'PAUSED',clear:'MAZE COMPLETE!',over:'GAME OVER'}[state]||'';$('#overlay-copy').textContent={ready:'Collect every dot. Watch the corners.',paused:'Press P, Escape or Pause to resume.',clear:'A faster maze awaits.',over:'Score '+game.score+' · High score '+best}[state]||'';$('#pause').textContent=state==='paused'?'Resume':'Pause'}
function start(){game=new Pacman();started=true;time=0;effects.length=0;lastOverlay='';$('#menu').hidden=true;canvas.focus();tone(550,.25);hud()}
function pause(){if(!started||game.state==='over')return;game.pause();hud()}
function tick(now){const dt=Math.min((now-last)/1000||0,.05);last=now;if(started&&game.state!=='paused'){time+=dt;game.update(dt);for(const e of game.events){if(e.kind==='chomp'&&Math.floor(time*20)%2===0)tone(300+game.eaten%3*70,.04);if(e.kind==='power')tone(650,.25);if(e.kind==='ghost-eaten')tone(900,.2);if(e.kind==='death')tone(150,.7);if(e.kind==='clear')tone(1000,.45);if(e.kind==='points'&&e.amount>=100)effects.push({x:e.x,y:e.y,text:'+'+e.amount,life:1})}for(const e of effects)e.life-=dt;for(let i=effects.length-1;i>=0;i--)if(effects[i].life<=0)effects.splice(i,1);hud()}draw();requestAnimationFrame(tick)}
$('#start').onclick=$('#again').onclick=start;$('#pause').onclick=pause;$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'Sound on':'Sound off';if(sound)tone()};$('#about').onclick=()=>{notesPaused=started&&game.state!=='paused'&&game.state!=='over';if(notesPaused)pause();$('#notes').showModal()};$('#notes-close').onclick=()=>$('#notes').close();$('#notes').addEventListener('close',()=>{if(notesPaused&&game.state==='paused')pause();notesPaused=false});
const keyDir={ArrowRight:0,KeyD:0,ArrowDown:1,KeyS:1,ArrowLeft:2,KeyA:2,ArrowUp:3,KeyW:3};window.addEventListener('keydown',e=>{if($('#notes').open)return;if(e.code==='KeyP'||e.code==='Escape'){e.preventDefault();pause();return}if(e.code==='Enter'&&(!started||game.state==='over')){start();return}if(keyDir[e.code]!==undefined){e.preventDefault();game.request(keyDir[e.code])}});$('#touch').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-dir]');if(b){e.preventDefault();game.request(Number(b.dataset.dir))}});canvas.addEventListener('pointerdown',e=>{swipe={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!swipe)return;const x=e.clientX-swipe.x,y=e.clientY-swipe.y;if(Math.hypot(x,y)<14)return;game.request(Math.abs(x)>Math.abs(y)?x>0?0:2:y>0?1:3);swipe={x:e.clientX,y:e.clientY}});for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,()=>swipe=null);window.addEventListener('blur',()=>{if(started&&game.state!=='paused'&&game.state!=='over')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&started&&game.state!=='paused'&&game.state!=='over')pause()});window.addEventListener('pagehide',()=>audio?.close().catch(()=>{}));
window.GameDiagnostics={get state(){return game.state},get snapshot(){return {score:game.score,lives:game.lives,level:game.level,pellets:game.pellets.size,fright:game.fright,ghosts:game.ghosts.map(g=>({name:g.name,mode:g.mode}))}}};if(new URLSearchParams(location.search).get('build')==='1')$('#notes').showModal();hud();requestAnimationFrame(tick);
